      "faq1A": "هي المسارات الكبرى بالسيارة نحو الموانئ التي لها خط نحو الجزائر في 2026: مرسيليا، سيت، برشلونة، فالنسيا، أليكانتي وألميريا. ونضيف إليها الطرق من موانئ الوصول الجزائرية (الغزوات، وهران، مستغانم، الجزائر العاصمة، بجاية، سكيكدة، عنابة) إلى المدن الكبرى.",
